def _native_grep_search(query: str, root_path: Path | None = None) -> str:
    """Fuzzy/regex search files recursively in the workspace as a fallback."""
    matches: list[str] = []
    p = root_path if root_path else Path(".")
    try:
        pattern = re.compile(query, re.IGNORECASE)
    except Exception:
        pattern = re.compile(re.escape(query), re.IGNORECASE)

    try:
        for path in p.rglob("*"):
            if path.is_file():
                parts = path.parts
                if not any(
                    ignored in parts
                    for ignored in (
                        ".git",
                        "node_modules",
                        ".buddhi",
                        ".venv",
                        "venv",
                        ".agents",
                        "__pycache__",
                    )
                ):
                    try:
                        with path.open("r", encoding="utf-8", errors="replace") as f:
                            for idx, line in enumerate(f, 1):
                                if pattern.search(line):
                                    display_path = (
                                        path.relative_to(p).as_posix()
                                        if root_path and path.is_relative_to(p)
                                        else path.as_posix()
                                    )
                                    matches.append(f"{display_path}:{idx}: {line.strip()}")
                                    if len(matches) >= 50:
                                        break
                    except Exception:
                        pass
            if len(matches) >= 50:
                break
    except Exception:
        pass

    if matches:
        return "### [fallback: native grep] Native Grep Fallback Matches:\n" + "\n".join(matches)
    return ""

