    """Extract or return signature and docstring from definition."""
    if signature and signature.strip():
        return signature.strip()

    if not content:
        return content

    lines = content.splitlines()
    nt = node_type.lower()
    if "function" in nt or "method" in nt or "class" in nt:
        sig_lines: list[str] = []
        found_colon = False
        for line in lines:
            sig_lines.append(line)
            if not found_colon and (line.rstrip().endswith(":") or line.rstrip().endswith("{")):
                found_colon = True
                continue
            if found_colon:
                stripped = line.strip()
                if stripped.startswith('"""') or stripped.startswith("'''") or stripped.startswith("/*"):
                    sig_lines.append(line)
                    if (
                        stripped.count('"""') >= 2
                        or stripped.count("'''") >= 2
                        or "*/" in stripped
                    ):
                        break
                    for remaining in lines[len(sig_lines) :]:
                        sig_lines.append(remaining)
                        if '"""' in remaining or "'''" in remaining or "*/" in remaining:
                            break
                break

        if sig_lines:
            return "\n".join(sig_lines)

    return lines[0] if lines else content

def filter_low_entropy_lines(content: str, threshold: float = _ENTROPY_THRESHOLD) -> str:
    """Remove lines with Shannon entropy below the threshold."""
    if not content:
        return content

    lines = content.splitlines()
    filtered: list[str] = []

    for line in lines:
        stripped = line.strip()
        if not stripped or len(stripped) < 10:
            filtered.append(line)
            continue

        entropy = calculate_entropy(stripped)
        if entropy >= threshold:
            filtered.append(line)

    return "\n".join(filtered)

def render_content(result: SearchResult) -> str:
    """Render node content according to its current mode."""
    if result.mode == "map":
        return extract_map_entry(result)

    if result.mode == "signatures":
        content = extract_signature(result.content, result.signature, result.node_type)
    else:
        content = result.content or result.signature

    return filter_low_entropy_lines(content)

def serialize_context(nodes: list[SearchResult]) -> str:
    """Serialize search results into delimited text with boundary markers."""
    if not nodes:
        return ""

    blocks: list[str] = []
    for result in nodes:
        header = f"--- START SYMBOL: {result.file_path}::{result.name} (L{result.start_line}-L{result.end_line}) ---"
        content = render_content(result)
        footer = "--- END SYMBOL ---"
        blocks.append(f"{header}\n{content}\n{footer}")

    return "\n\n".join(blocks)

def split_frontmatter(content: str) -> tuple[dict[str, Any], str]:
    """Splits YAML frontmatter from markdown body.

    Returns (metadata_dict, body_str). If no frontmatter delimiter is present,
    returns ({}, content).
    """
    match = _FRONTMATTER_SPLIT_RE.match(content)
    if not match:
        return {}, content.strip()

    raw_yaml, body = match.group(1), match.group(2)
    try:
        data = yaml.safe_load(raw_yaml) or {}
    except (yaml.YAMLError, OSError, ValueError):
        data = {}

    if not isinstance(data, dict):
        data = {}

    # Reject forbidden Attested Computation fields
    for forbidden in _FORBIDDEN_OKF_FIELDS:
        data.pop(forbidden, None)

    return data, body.strip()

def compute_content_hash(workspace_root: Path, resource: str) -> str:
    """Computes SHA-256 of full file or line slice #Lstart-Lend with normalized LF line endings."""
    file_path, start_line, end_line = parse_source_resource(resource, workspace_root)
    if not file_path.is_file():
        raise FileNotFoundError(f"Source file not found: {file_path}")

    raw_text = file_path.read_text(encoding="utf-8")
    # Normalize CRLF -> LF for cross-platform hash parity
    normalized = raw_text.replace("\r\n", "\n")

    if start_line is not None and end_line is not None:
        lines = normalized.splitlines(keepends=True)
        # 1-indexed line numbers
        selected = lines[start_line - 1 : end_line]
        slice_text = "".join(selected)
    else:
        slice_text = normalized

    return hashlib.sha256(slice_text.encode("utf-8")).hexdigest()

def verify_source_staleness(
    workspace_root: Path, source: MemorySource
) -> StalenessResult:
    """Checks whether the on-disk code snippet still matches source.content_hash."""
    try:
        current_hash = compute_content_hash(workspace_root, source.resource)
    except FileNotFoundError:
        return StalenessResult(
            is_stale=True,
            reason="file_not_found",
            expected_hash=source.content_hash,
            current_hash="",
        )
    except ValueError as exc:
        return StalenessResult(
            is_stale=True,
            reason=f"invalid_resource: {exc}",
            expected_hash=source.content_hash,
            current_hash="",
        )

    if current_hash != source.content_hash:
        return StalenessResult(
            is_stale=True,
            reason="hash_mismatch",
            expected_hash=source.content_hash,
            current_hash=current_hash,
        )

    return StalenessResult(
        is_stale=False,
        reason=None,
        expected_hash=source.content_hash,
        current_hash=current_hash,
    )

def is_boilerplate(line: str) -> bool:
    """Check if line is template boilerplate rather than user entry."""
    cleaned = line.lower().strip()
    return any(bp in cleaned for bp in BOILERPLATE_SUBSTRINGS)

def parse_legacy_entries(text: str) -> list[str]:
    """Parse distinct bullet points, numbered items, or paragraph entries."""
    lines = text.splitlines()
    entries: list[str] = []
    current_entry: list[str] = []

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if is_boilerplate(stripped):
            continue

        if stripped.startswith(("- ", "* ", "+ ")) or re.match(r"^\d+\.\s+", stripped):
            if current_entry:
                entries.append(" ".join(current_entry))
                current_entry = []
            clean_item = re.sub(r"^[-*+\d.]+\s*", "", stripped)
            current_entry.append(clean_item)
        else:
            current_entry.append(stripped)

    if current_entry:
        entries.append(" ".join(current_entry))

    return [e.strip() for e in entries if e.strip()]

def matches_active_files(patterns: list[str], active_files: list[str]) -> bool:
    """Returns True if patterns is empty (global) or matches any active file."""
    if not patterns:
        return True

    if not active_files:
        return False

    normalized_files = [f.replace("\\", "/").lstrip("/") for f in active_files]
    spec = pathspec.PathSpec.from_lines("gitignore", patterns)

    for f in normalized_files:
        if spec.match_file(f):
            return True

    return False

def _find_spec_dir(workspace_root: Path, branch: str | None = None) -> Path | None:
    specs_root = workspace_root / ".buddhi" / "specs"
    if not specs_root.is_dir():
        return None

    if branch:
        target = specs_root / branch
        if target.is_dir():
            return target
        done_target = specs_root / "done" / branch
        if done_target.is_dir():
            return done_target
        return None

    # Search for any active spec directory with spec.md
    candidates = [
        d
        for d in specs_root.iterdir()
        if d.is_dir() and d.name != "done" and (d / "spec.md").is_file()
    ]
    if candidates:
        return candidates[0]

    return None

def assert_no_secrets_in_tracked_memory(content: str, scope: str) -> None:
    """Blocks secrets/credentials from being persisted into git-tracked scopes."""
    if scope in ("local", "agent-local"):
        return

    for pattern in SECRET_PATTERNS:
        if pattern.search(content):
            raise PermissionError(
                "Potential secret or credential detected in memory content. "
                "Credentials must never be saved to git-tracked 'project' memory. "
                "Use scope 'local' or store credentials in environment variables."
            )

def parse_source_resource(
    resource: str, workspace_root: Path
) -> tuple[Path, int | None, int | None]:
    """Parses and validates a code source anchor ('path/file.py#L10-L20')."""
    path_part, _, line_part = resource.partition("#")
    cleaned = path_part.strip().replace("\\", "/")
    if cleaned.startswith(("/", "\\")) or ".." in Path(cleaned).parts:
        raise PermissionError(
            f"Source resource '{resource}' uses absolute or parent traversal path"
        )

    target = (workspace_root / cleaned).resolve()
    ws_resolved = workspace_root.resolve()
    if not target.is_relative_to(ws_resolved):
        raise PermissionError(f"Source resource '{resource}' escapes workspace root")

    start_line, end_line = None, None
    if line_part:
        m = re.match(r"^L(\d+)(?:-L(\d+))?$", line_part.strip())
        if not m:
            raise ValueError(f"Invalid line range in source anchor: #{line_part}")
        start_line = int(m.group(1))
        end_line = int(m.group(2)) if m.group(2) else start_line
        if start_line <= 0 or end_line < start_line:
            raise ValueError(f"Invalid line range bounds: L{start_line}-L{end_line}")

    return target, start_line, end_line

def resolve_and_sandbox_import(
    raw_ref: str,
    base_dir: Path,
    workspace_root: Path,
    user_memory_root: Path,
) -> Path:
    """Resolves an `@path` import string while strictly enforcing workspace / user-memory sandboxing."""
    cleaned = raw_ref.lstrip("@").strip()
    if "\0" in cleaned or "\r" in cleaned or "\n" in cleaned:
        raise ValueError(f"Invalid characters in import path: '{raw_ref}'")

    if cleaned.startswith(("\\\\", "//")):
        raise PermissionError(f"UNC network paths forbidden: '{raw_ref}'")

    # Base path resolution
    if cleaned.startswith("~"):
        target = Path(cleaned).expanduser()
    elif cleaned.startswith("/") or (
        len(cleaned) > 2 and cleaned[1] == ":" and cleaned[2] in "\\/"
    ):
        target = Path(cleaned)
    else:
        # Relative to current file directory if exists, otherwise relative to workspace root
        from_base = (base_dir / cleaned).resolve()
        if from_base.exists():
            target = from_base
        else:
            target = (workspace_root / cleaned).resolve()

    try:
        resolved = target.resolve(strict=True)
    except (FileNotFoundError, RuntimeError, OSError) as exc:
        raise FileNotFoundError(f"Cannot resolve import '{raw_ref}': {exc}") from exc

    ws_resolved = workspace_root.resolve()
    user_resolved = user_memory_root.resolve()

    in_workspace = resolved.is_relative_to(ws_resolved)
    in_user = resolved.is_relative_to(user_resolved)

    if not (in_workspace or in_user):
        raise PermissionError(
            f"Sandbox escape blocked: '{raw_ref}' resolves outside permitted roots"
        )

    if not resolved.is_file():
        raise ValueError(f"Import target is not a regular file: '{raw_ref}'")

    return resolved

def build_memory_file_path(base_memory_dir: Path, kind: str, slug: str) -> Path:
    """Builds and validates an atomic concept file path inside base_memory_dir."""
    if ".." in slug or "/" in slug or "\\" in slug:
        raise PermissionError(
            f"Slug traversal blocked: '{slug}' contains path separators or traversal characters"
        )
    topic_sub = TOPIC_DIRS.get(kind, "misc")
    clean_slug = sanitize_slug(slug)
    target = (base_memory_dir / topic_sub / f"{clean_slug}.md").resolve()
    base_resolved = base_memory_dir.resolve()
    if not target.is_relative_to(base_resolved):
        raise PermissionError(
            f"Slug traversal blocked: '{slug}' resolves outside memory base directory"
        )
    return target

def atomic_write_bytes(path: Path, data: bytes) -> None:
    tmp_path = path.with_name(f"{path.name}.tmp-{os.getpid()}")
    try:
        tmp_path.write_bytes(data)
        os.replace(tmp_path, path)
    except BaseException:
        tmp_path.unlink(missing_ok=True)
        raise

def _community_color(community_id: int) -> dict[str, str]:
    hue = (community_id * 0.618033988749895) % 1.0
    r, g, b = colorsys.hsv_to_rgb(hue, 0.6, 0.9)
    background = f"#{int(r * 255):02x}{int(g * 255):02x}{int(b * 255):02x}"
    return {"background": background, "border": "#f8fafc"}

def _legend_html() -> str:
    return "".join(
        _LEGEND_ITEM.format(color=_KIND_COLORS[kind]["background"], label=label, kind=kind)
        for kind, label in _KIND_LABELS
    )

def _node_color(kind: str, community_id: int | None) -> dict[str, str]:
    if kind in _CLUSTERABLE_KINDS and community_id is not None:
        return _community_color(community_id)
    return _KIND_COLORS.get(kind, {"background": "#3b82f6", "border": "#60a5fa"})

def _build_vis_data(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        color = _node_color(node.kind, node.community_id)
        nodes.append(
            {
                "id": node.id,
                "label": node.name,
                "kind": node.kind,
                "qualified_name": node.qualified_name,
                "file_path": node.file_path,
                "start_line": node.start_line,
                "end_line": node.end_line,
                "snippet": node.snippet,
                "community_id": node.community_id,
                "color": {
                    "background": color["background"],
                    "border": color["border"],
                    "highlight": {"background": color["background"], "border": "#f8fafc"},
                    "hover": {"background": color["background"], "border": "#f8fafc"},
                },
            }
        )

    edges = []
    for edge in graph.edges:
        if edge.kind == CONTAINS:
            continue
        edges.append(
            {
                "from": edge.source,
                "to": edge.target,
                "kind": edge.kind,
                "color": {"color": _EDGE_COLORS.get(edge.kind, "#64748b"), "opacity": 0.5},
            }
        )

    return {"nodes": nodes, "edges": edges}

def to_cytoscape_elements(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        data = {
            "id": node.id,
            "label": node.name,
            "kind": node.kind,
            "qualified_name": node.qualified_name,
            "file_path": node.file_path,
            "language": node.language,
            "start_line": node.start_line,
            "end_line": node.end_line,
            "external": node.external,
            "snippet": node.snippet,
            "community_id": node.community_id,
        }
        if node.parent_id:
            data["parent"] = node.parent_id
        nodes.append({"data": data})

    edges = []
    for i, edge in enumerate(graph.edges):
        edges.append(
            {
                "data": {
                    "id": f"e{i}",
                    "source": edge.source,
                    "target": edge.target,
                    "kind": edge.kind,
                    "resolved": edge.resolved,
                }
            }
        )

    return {"nodes": nodes, "edges": edges}

def read_settings(file: Path | None = None) -> dict[str, Any]:
    target = file if file is not None else settings_path
    if not target.exists():
        return {}
    try:
        data = json.loads(target.read_text(encoding="utf-8"))
    except Exception as exc:
        raise ValueError(f"Cannot read {target}: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Expected a JSON object in {target}")  # noqa: TRY004
    return data

def configure_mode(mode: str | None = None, file: Path | None = None) -> str:
    target = file if file is not None else settings_path
    if mode is not None and mode not in MODES:
        raise ValueError(f"Invalid mode in {target}. Set --mode during, after, or ask.")

    try:
        settings = read_settings(target)
    except ValueError as exc:
        raise ValueError(f"{exc} Fix or delete it to start over.") from exc

    if mode is not None:
        settings["mode"] = mode
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(json.dumps(settings, indent=2) + "\n", encoding="utf-8")

    resolved_mode = settings.get("mode") or "ask"
    if resolved_mode not in MODES:
        raise ValueError(f"Invalid mode in {target}. Set --mode during, after, or ask.")

    default_indicator = " (default)" if "mode" not in settings else ""
    return f"antislop global mode: {resolved_mode}{default_indicator}\n{target}"

def format_tokens(num_bytes: int) -> str:
    toks = round(num_bytes / 4)
    return f"~{toks:,} tokens"

def get_unauthored(paths: list[str]) -> set[str]:
    """Return paths marked linguist-generated or linguist-vendored in git index."""
    if not paths:
        return set()
    input_data = "\0".join(paths).encode("utf-8")
    try:
        proc = subprocess.run(
            [
                "git",
                "check-attr",
                "--cached",
                "-z",
                "--stdin",
                "linguist-generated",
                "linguist-vendored",
            ],
            input=input_data,
            capture_output=True,
            check=True,
        )
        parts = proc.stdout.decode("utf-8", errors="replace").split("\0")
        marked = set()
        for i in range(0, len(parts) - 2, 3):
            attr_val = parts[i + 2]
            if attr_val in ("true", "set"):
                marked.add(parts[i])
        return marked
    except (subprocess.CalledProcessError, OSError):
        return set()

def is_ignored(spec: str) -> bool:
    """Check if the first PRAGMA_LINES contain @ratchet-files-ignore."""
    try:
        proc = subprocess.run(
            ["git", "cat-file", "blob", spec],
            capture_output=True,
            check=True,
        )
        lines = proc.stdout.decode("utf-8", errors="replace").splitlines()
        first_lines = lines[:PRAGMA_LINES]
        return any(PRAGMA in line for line in first_lines)
    except (subprocess.CalledProcessError, OSError):
        return False

def is_source_file(path_str: str) -> bool:
    ext = os.path.splitext(path_str)[1].lower()
    if not ext:
        return False
    return ext in CODE_EXTENSIONS and ext not in PROSE_EXTENSIONS

def run_git(args: list[str], input_bytes: bytes | None = None) -> str:
    """Execute git with pipe stdio and utf-8 decoding."""
    result = subprocess.run(
        ["git", *args],
        input=input_bytes,
        capture_output=True,
        check=True,
    )
    return result.stdout.decode("utf-8", errors="replace")

def blob_bytes(spec: str) -> int | None:
    """Return byte size of a git blob spec (e.g. ':path' or 'HEAD:path')."""
    try:
        out = run_git(["cat-file", "-s", spec]).strip()
        return int(out)
    except (subprocess.CalledProcessError, OSError, ValueError):
        return None

def get_git_root() -> Path:
    """Return git repo toplevel directory."""
    out = run_git(["rev-parse", "--show-toplevel"]).strip()
    return Path(out).resolve()

def linearize(channel: int) -> float:
    c = channel / 255.0
    if c <= 0.03928:
        return c / 12.92
    return ((c + 0.055) / 1.055) ** 2.4

def luminance(rgb: tuple[int, int, int]) -> float:
    r, g, b = (linearize(ch) for ch in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast_ratio(
    color_a: tuple[int, int, int], color_b: tuple[int, int, int]
) -> float:
    lum_a, lum_b = luminance(color_a), luminance(color_b)
    lighter, darker = max(lum_a, lum_b), min(lum_a, lum_b)
    return (lighter + 0.05) / (darker + 0.05)

def parse_hex(value: str) -> tuple[int, int, int]:
    clean = value.strip().lstrip("#")
    if len(clean) == 3:
        clean = "".join(ch * 2 for ch in clean)
    if not re.fullmatch(r"[0-9A-Fa-f]{6}", clean):
        raise ValueError(f"expected a hex color like #FFFFFF, got {value!r}")
    return (int(clean[0:2], 16), int(clean[2:4], 16), int(clean[4:6], 16))

def parse_color(value: str) -> tuple[int, int, int]:
    val = value.strip().lower()
    if val in NAMED_COLORS:
        return NAMED_COLORS[val]
    return parse_hex(value)

def parse_pairing(pairing: str) -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    """Turn 'White on #333333' or '#555555 on black' into two RGB tuples."""
    colors = []
    for token in re.split(r"\s+on\s+", pairing):
        token = token.strip()
        match = re.search(r"#[0-9A-Fa-f]{3,6}", token)
        if match:
            colors.append(parse_hex(match.group(0)))
        elif token.lower() in NAMED_COLORS:
            colors.append(NAMED_COLORS[token.lower()])
        else:
            raise ValueError(f"cannot parse {token!r} from pairing {pairing!r}")
    if len(colors) != 2:
        raise ValueError(f"expected two colors in pairing {pairing!r}")
    return (colors[0], colors[1])

def parse_reference_rows(text: str) -> list[dict[str, str | float]]:
    rows: list[dict[str, str | float]] = []
    in_table = False
    for raw in text.splitlines():
        line = raw.strip()
        if line.startswith(REFERENCE_HEADER):
            in_table = True
            continue
        if not in_table:
            continue
        if not line.startswith("|"):
            break
        if line.startswith("|---"):
            continue
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if len(cells) != 4:
            continue
        pairing, ratio_str, normal, large = cells
        rows.append(
            {
                "pairing": pairing,
                "ratio": float(ratio_str),
                "normal": normal,
                "large": large,
            }
        )
    return rows

def selftest() -> tuple[int, str]:
    text = _get_skill_doc_text()
    if text is None:
        return (
            2,
            "selftest: antislop-human/SKILL.md reference doc not found; cannot check table",
        )

    try:
        rows = parse_reference_rows(text)
    except Exception as exc:  # noqa: BLE001
        return 1, f"selftest: could not read table from SKILL.md: {exc}"

    if not rows:
        return 1, "selftest: no reference rows found in SKILL.md"

    failures = []
    for row in rows:
        pairing_str = str(row["pairing"])
        color_a, color_b = parse_pairing(pairing_str)
        raw = contrast_ratio(color_a, color_b)
        computed = round(raw, 2)
        expected_normal = "Pass" if raw >= 4.5 else "Fail"
        expected_large = "Pass" if raw >= 3.0 else "Fail"

        if f"{computed:.2f}" != f"{float(row['ratio']):.2f}":
            failures.append(
                f"selftest: {pairing_str}: table says {row['ratio']}, formula says {computed:.2f}"
            )
        if row["normal"] != expected_normal:
            failures.append(
                f"selftest: {pairing_str}: normal text marked {row['normal']}, should be {expected_normal}"
            )
        if row["large"] != expected_large:
            failures.append(
                f"selftest: {pairing_str}: large text marked {row['large']}, should be {expected_large}"
            )

    if failures:
        return 1, "\n".join(failures)
    return 0, f"selftest: {len(rows)} reference pairs OK"

def looks_like_argument(token: str) -> bool:
    if token.startswith("-"):
        return True
    if "/" in token or "\\" in token:
        return True
    if re.search(r"\.\w{1,6}$", token):
        return True
    if "=" in token:
        return True
    if token.startswith(("'", '"')) or "%[" in token or "{" in token:
        return True
    if re.match(r"^\w+:$", token):
        return True
    return bool(token.startswith(("$", "@", "#")))

def is_invocation(line: str) -> bool:
    stripped = re.sub(r"^\s*[$>]\s+", "", line).strip()
    if not stripped:
        return False
    tokens = stripped.split()
    head = os.path.basename(tokens[0])
    runnable = (
        head in TOOLS
        or tokens[0].startswith(("./", "../", "/"))
        or bool(re.match(r"^\w[\w.-]*\.(?:mjs|js|py|sh)$", head))
    )
    if not runnable:
        return False
    return any(looks_like_argument(t) for t in tokens[1:])

def parse_receipt_lines(lines: list[str]) -> list[bool]:
    """Flag which lines belong to a fenced block, indented code, or shell transcript."""
    in_receipt = [False] * len(lines)
    fence: str | None = None
    transcript = False

    for i, line in enumerate(lines):
        fence_match = re.match(r"^\s*(`{3,}|~{3,})", line)
        if fence_match:
            if fence is None:
                fence = fence_match.group(1)[:3]
                in_receipt[i] = True
                continue
            if fence_match.group(1).startswith(fence):
                fence = None
                in_receipt[i] = True
                continue
        if fence is not None:
            in_receipt[i] = True
            continue

        if re.match(r"^\s{4,}\S", line) and not re.match(r"^\s*[-*+]\s", line):
            in_receipt[i] = True
            continue

        if re.match(r"^\s*\$\s+\S", line):
            in_receipt[i] = True
            transcript = True
            continue
        if transcript:
            if not line.strip():
                transcript = False
            else:
                in_receipt[i] = True

    return in_receipt

def extract_receipt_runs(lines: list[str]) -> list[ReceiptRun]:
    """Group contiguous receipt lines into runs and collect command and outputs."""
    in_receipt = parse_receipt_lines(lines)
    runs: list[ReceiptRun] = []
    i = 0
    n = len(lines)

    while i < n:
        if not in_receipt[i]:
            i += 1
            continue
        start = i
        while i < n and in_receipt[i]:
            i += 1
        end = i

        block_lines = lines[start:end]
        inv_idx = -1
        for idx, bline in enumerate(block_lines):
            if is_invocation(bline):
                inv_idx = idx
                break

        if inv_idx != -1 and inv_idx + 1 < len(block_lines):
            cmd = block_lines[inv_idx].strip()
            out_lines = [l for l in block_lines[inv_idx + 1 :] if not is_invocation(l)]
            if out_lines:
                run = ReceiptRun(
                    start_line=start, end_line=end, command=cmd, output_lines=out_lines
                )
                for ol in out_lines:
                    for m in NUMBER_RE.finditer(ol):
                        run.numbers.add(m.group(1))
                    for m in HEX_RE.finditer(ol):
                        run.hexes.add(m.group(1).lower())
                runs.append(run)

    return runs

