    try:
        existing = gitignore_path.read_text(encoding="utf-8") if gitignore_path.exists() else ""
        lines = [line.strip() for line in existing.splitlines()]
        added = []
        for rule in AGENTS_GITIGNORE_RULES:
            if rule not in lines:
