def detect_rate(base, reduction, trials, boots, n, rng):
    hits = 0
    for _ in range(trials):
        ref = rng.choice(base, n)
        trt = rng.binomial(rng.choice(base, n).astype(int), 1 - reduction)
        diffs = np.array([rng.choice(trt, n).mean() - rng.choice(ref, n).mean()
                          for _ in range(boots)])
        if np.percentile(diffs, 97.5) < 0:
            hits += 1
    return hits / trials

def boot_mean_diff(x, y, n=10000, seed=20260819):
    if not x or not y: return None
    rng = random.Random(seed)
    diffs = sorted(statistics.fmean(rng.choices(x, k=len(x))) -
                   statistics.fmean(rng.choices(y, k=len(y))) for _ in range(n))
    return {"diff": statistics.fmean(x) - statistics.fmean(y),
            "lo": diffs[int(n*0.025)], "hi": diffs[int(n*0.975)]}

