def contrast_verdict(d18_affected: int, d20_affected: int) -> str:
    if d20_affected > d18_affected: return "refuted"
    if (d18_affected > 0 and d20_affected < d18_affected) or (d18_affected == 0 and d20_affected == 0):
        return "corroborated"
