    else { console.error(`unknown arg: ${v[i]}`); process.exit(2); }
  }
  if (!a.dirs.length || !a.out) {
    console.error('usage: node verify.js --dir DIR [--dir DIR2] --out FILE.jsonl [--shots DIR] [--resume]');
    process.exit(2);
  }
  return a;
}

function checkAxe() {
  const dir = path.resolve(__dirname, '..', 'harness');
  const lock = fs.readFileSync(path.join(dir, 'axe.lock'), 'utf8');
  const version = (lock.match(/version:\s*(\S+)/) || [])[1];
  const expected = (lock.match(/sha256:\s*([0-9a-f]{64})/) || [])[1];
  const source = fs.readFileSync(path.join(dir, 'axe.min.js'));
  const actual = crypto.createHash('sha256').update(source).digest('hex');
  if (actual !== expected) {
    console.error(`axe.min.js does not match axe.lock (${actual} != ${expected})`);
    process.exit(1);
  }
  return { source: source.toString('utf8'), version };
}

function serve(dirs) {
  // /0/<file>, /1/<file> — one prefix per --dir, nothing else reachable.
  return http.createServer((req, res) => {
    const m = req.url.match(/^\/(\d+)\/(.+)$/);
    const dir = m && dirs[Number(m[1])];
    const file = dir && path.join(dir, decodeURIComponent(m[2]));
    if (!file || !file.startsWith(dir) || !fs.existsSync(file)) {
      res.writeHead(404).end();
      return;
    }
    // fix 2026-08-24: every file was served as text/html, so browsers silently
    // rejected external stylesheets (strict MIME for <link rel=stylesheet>).
    // Study 2 was the first design with non-inlined assets — see DEVIATIONS.md.
    const MIME = { '.html': 'text/html; charset=utf-8', '.css': 'text/css',
                   '.js': 'text/javascript', '.svg': 'image/svg+xml',
                   '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp',
                   '.json': 'application/json' };
    const type = MIME[path.extname(file).toLowerCase()] || 'application/octet-stream';
    res.writeHead(200, { 'content-type': type });
    res.end(fs.readFileSync(file));
  });
}

def composite(fg, bg):
    """Composite fg (with alpha) over an opaque bg. Returns opaque (r, g, b)."""
    a = fg[3]
    return tuple(fg[i] * a + bg[i] * (1 - a) for i in range(3))

def parse_color(token: str):
    """Return (r, g, b, a) in 0–255 / 0–1, or None if unparseable."""
    t = token.strip().lower()
    if t in NAMED:
        return NAMED[t]
    if t.startswith("#"):
        h = t[1:]
        if len(h) in (3, 4):
            h = "".join(c * 2 for c in h)
        if len(h) == 6:
            h += "ff"
        if len(h) != 8:
            return None
        r, g, b, a = (int(h[i:i + 2], 16) for i in (0, 2, 4, 6))
        return (r, g, b, a / 255.0)
    m = re.match(r"(rgba?|hsla?)\(([^)]+)\)", t)
    if not m:
        return None
    fn, body = m.group(1), m.group(2)
    parts = [p.strip() for p in re.split(r"[,/]", body) if p.strip()]
    if len(parts) < 3:
        return None
    try:
        if fn.startswith("rgb"):
            vals = []
            for p in parts[:3]:
                vals.append(float(p[:-1]) * 2.55 if p.endswith("%") else float(p))
            a = float(parts[3][:-1]) / 100 if len(parts) > 3 and parts[3].endswith("%") \
                else float(parts[3]) if len(parts) > 3 else 1.0
            r, g, b = (_clamp(v) for v in vals)
            return (r, g, b, a)
        # hsl
        h = float(re.sub(r"deg$", "", parts[0]))
        s = float(parts[1].rstrip("%")) / 100
        l = float(parts[2].rstrip("%")) / 100
        a = float(parts[3][:-1]) / 100 if len(parts) > 3 and parts[3].endswith("%") \
            else float(parts[3]) if len(parts) > 3 else 1.0
        c = (1 - abs(2 * l - 1)) * s
        x = c * (1 - abs((h / 60) % 2 - 1))
        mm = l - c / 2
        r1, g1, b1 = (
            (c, x, 0) if h < 60 else (x, c, 0) if h < 120 else
            (0, c, x) if h < 180 else (0, x, c) if h < 240 else
            (x, 0, c) if h < 300 else (c, 0, x)
        )
        return ((r1 + mm) * 255, (g1 + mm) * 255, (b1 + mm) * 255, a)
    except ValueError:
        return None

def check_links(root: Path) -> None:
    for lang in LANGS:
        base = root / "docs" / lang
        for path in [core(root, lang)] + sorted(base.glob("templates/*.md")) + sorted(base.glob("references/*.md")):
            text = path.read_text(encoding="utf-8")
            for target in re.findall(r"\]\((?!https?:|#|mailto:)([^)]+)\)", text):
                resolved = (path.parent / target.split("#")[0]).resolve()
                if not resolved.exists():
                    fail("links", f"{path.relative_to(root)} → broken relative link '{target}'")

def check_optional_label(root: Path) -> None:
    for path in sorted((root / "docs").rglob("*.md")):
        for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            if re.search(r"(Optional Templates|Templates Opcionais)", line):
                fail("optional",
                     f"{path.relative_to(root)}:{line_no} — project artifacts labelled optional while the "
                     f"body requires them. This exact contradiction caused the 2026-08-01 field failure.")

def check_orphans(root: Path) -> None:
    for lang in LANGS:
        text = core(root, lang).read_text(encoding="utf-8")
        linked = set(re.findall(r"guide-[a-z0-9-]+\.md", text))
        on_disk = {p.name for p in (root / "docs" / lang / "references").glob("guide-*.md")}
        for orphan in sorted(on_disk - linked):
            fail("orphans", f"docs/{lang}/references/{orphan} is not linked from the core file — "
                            f"lazy loading can never discover it")

def check_parity(root: Path) -> None:
    listings = {}
    for lang in LANGS:
        base = root / "docs" / lang
        listings[lang] = {p.relative_to(base).as_posix() for p in base.rglob("*.md")}
    only_en = listings["en"] - listings["pt-BR"]
    only_pt = listings["pt-BR"] - listings["en"]
    for name in sorted(only_en):
        fail("parity", f"docs/en/{name} has no pt-BR counterpart")
    for name in sorted(only_pt):
        fail("parity", f"docs/pt-BR/{name} has no en counterpart")

    counts = {}
    for lang in LANGS:
        text = core(root, lang).read_text(encoding="utf-8")
        contract = re.search(r"## 2\..*?(?=\n## 3\.)", text, re.S)
        counts[lang] = (
            len(re.findall(r"^#{1,6} ", text, re.M)),
            len(re.findall(r"^- \*\*", contract.group(0), re.M)) if contract else 0,
        )
    if counts["en"][0] != counts["pt-BR"][0]:
        fail("parity", f"heading count differs: en={counts['en'][0]} pt-BR={counts['pt-BR'][0]}")
    if counts["en"][1] != counts["pt-BR"][1]:
        fail("parity", f"AI Behavior Contract rule count differs: "
                       f"en={counts['en'][1]} pt-BR={counts['pt-BR'][1]}")

def check_phase_triggers(root: Path) -> None:
    """Phase triggers never fire in continuously delivered projects."""
    patterns = (
        re.compile(r"(in case of|at|on|upon)\s+final\s+delivery", re.I),
        re.compile(r"em caso de entrega final|na entrega final", re.I),
        re.compile(r"(at|during)\s+(the\s+)?(final\s+)?QA cycle", re.I),
        re.compile(r"no ciclo de QA", re.I),
    )
    for path in sorted((root / "docs").rglob("*.md")):
        for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            # the design principle in the governance guide quotes these on purpose
            if "gatilhos por fase" in line or "phase triggers" in line:
                continue
            for pattern in patterns:
                if pattern.search(line):
                    fail("phase-trigger",
                         f"{path.relative_to(root)}:{line_no} — rule fires on a project phase, not an event. "
                         f"Use 'before any delivery to an end user' (see Release Evidence, §2).")

def check_wiki_drift(root: Path) -> None:
    """The Wiki is the project's public documentation but lives outside version
    control (see .gitignore), so nothing stops it from drifting away from the
    standard it documents. Skipped when the folder is absent — most clones
    will not have it."""
    wiki = root / "WIKI"
    if not wiki.is_dir():
        return

    contract = re.search(r"## 2\..*?(?=\n## 3\.)", core(root, "en").read_text(encoding="utf-8"), re.S)
    core_rules = len(re.findall(r"^- \*\*", contract.group(0), re.M)) if contract else 0
    page = wiki / "AI-Behavioral-Contract.md"
    if page.is_file():
        wiki_rules = len(re.findall(r"^### \d+\. ", page.read_text(encoding="utf-8"), re.M))
        if wiki_rules != core_rules:
            fail("wiki", f"WIKI/AI-Behavioral-Contract.md documents {wiki_rules} rules, "
                         f"the core file defines {core_rules}")

    library = wiki / "Reference-Library.md"
    if library.is_file():
        listed = set(re.findall(r"guide-[a-z0-9-]+\.md", library.read_text(encoding="utf-8")))
        on_disk = {p.name for p in (root / "docs" / "en" / "references").glob("guide-*.md")}
        for missing in sorted(on_disk - listed):
            fail("wiki", f"WIKI/Reference-Library.md does not list {missing}")

def main() -> int:
    root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    if not core(root, "en").is_file():
        print(f"error: {root} does not look like the A11Y.md repository", file=sys.stderr)
        return 2

    for check in (check_parity, check_orphans, check_triggers, check_links,
                  check_phase_triggers, check_placement, check_optional_label, check_wiki_drift):
        check(root)

    for name, message in findings:
        print(f"✗ [{name}] {message}")
    print()
    print(f"FAIL — {len(findings)} issue(s)." if findings else "PASS — standard is internally consistent.")
    return 1 if findings else 0

def as_path(token: str) -> str:
    path = token.strip().replace("\\", "/")
    while path.startswith("./"):
        path = path[2:]
    return path.strip("/")

def chooses(markup: str, subject: str) -> bool:
    """The flagged element carries the markup the decision chose, whole and as
    its own attribute: `role="list"` is not inside `role="listitem"`, nor
    inside `data-role="list"`, nor inside another attribute's value."""
    norm = lambda t: re.sub(r"\s+", " ", re.sub(r"\s*([=:])\s*", r"\1", t.replace("'", '"')))
    return bool(re.search(r"(?:^|(?<=[\s<{;,(]))" + re.escape(norm(markup)) + r"(?![\w-])", norm(subject)))

def expiry_of(block: str) -> dt.date | None:
    expiry = re.search(r"(?:Expiry|Expiração)[^:\n]*:\*{0,2}[ \t]*\[?(\d{4}-\d{2}-\d{2})", block)
    return dt.date.fromisoformat(expiry.group(1)) if expiry else None

def filled(field: re.Match | None) -> bool:
    """A field with a value that is not the template's bracketed placeholder."""
    return bool(field and field.group(1).strip() and not field.group(1).lstrip().startswith("["))

def git(root: Path, *args: str) -> str | None:
    try:
        out = subprocess.run(["git", "-C", str(root), *args],
                             capture_output=True, text=True, timeout=15)
        return out.stdout.strip() if out.returncode == 0 else None
    except (OSError, subprocess.SubprocessError):
        return None

def hex_rgb(token: str) -> tuple[int, int, int]:
    h = token.lstrip("#")
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)

def missing_fields(block: str) -> list[str]:
    missing = []
    for field, pattern in SIGN_OFF:
        m = re.search(pattern + r":\*{0,2}[ \t]*(.*)", block)
        if not m or not m.group(2).strip() or PLACEHOLDER.search(m.group(2)):
            missing.append(field)
    return missing

def normalize_hex(token: str) -> str:
    h = token.lstrip("#").lower()
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return h

def read(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None

def body_of(report: Path) -> str:
    """The report without its blockquotes: the template explains every field
    inside `>` notes, and a document-wide search would find the explanation."""
    text = read(report) or ""
    return "\n".join(l for l in text.splitlines() if not l.lstrip().startswith(">"))

def check_gitignore(root: Path) -> None:
    """Artifacts are versioned records; hiding them defeats their purpose."""
    gitignore = root / ".gitignore"
    if not gitignore.is_file():
        return
    patterns = [l.strip() for l in (read(gitignore) or "").splitlines()
                if l.strip() and not l.startswith("#")]
    for artifact in ARTIFACTS:
        for pattern in patterns:
            if pattern.strip("/") == artifact or pattern in ("*.md", "**/*.md"):
                fail("gitignore", f"{artifact} is excluded by .gitignore rule '{pattern}'. "
                                  f"Project artifacts must be versioned.")
                break

def source_files(root: Path, src: Path):
    for path in src.rglob("*"):
        if path.is_file() and path.suffix.lower() in SOURCE_SUFFIXES:
            if not any(part in SKIP_DIRS for part in path.relative_to(root).parts):
                yield path

def check_report_freshness(root: Path, report: Path, src: Path) -> None:
    """The report must be newer than the last interface change."""
    last_ui = git(root, "log", "-1", "--format=%cI", "--", str(src.relative_to(root)) if src != root else ".")
    last_report = git(root, "log", "-1", "--format=%cI", "--", "REPORT.md")
    if last_ui and last_report:
        if last_report < last_ui:
            fail("freshness", f"REPORT.md (last commit {last_report[:10]}) is older than the last "
                              f"interface change ({last_ui[:10]}). Revisit the entries that change affects.")
        return
    # no git history available — fall back to mtime
    newest = max((p.stat().st_mtime for p in source_files(root, src)), default=None)
    if newest and report.stat().st_mtime < newest:
        fail("freshness", "REPORT.md is older than the most recently modified source file.")

def status_claims_pass(body: str) -> bool:
    status = re.search(r"(?:Compliance Status|Status de Conformidade):?\*{0,2}[ \t]*(.*)", body, re.I)
    value = status.group(1).strip() if status else ""
    conditional = re.search(r"CONDITIONAL|CONDICIONAL", value, re.I)
    return bool(not conditional and (re.search(r"\bPASS\b", value, re.I) or "✅" in value))

def check_exceptions(root: Path) -> None:
    """Every exception needs owner, approver, tracking issue and a future expiry."""
    today = dt.date.today()
    for label, block in exception_entries(root):
        for field in missing_fields(block):
            fail("exceptions", f"{label}: missing {field}.")
        date = expiry_of(block)
        if not date:
            fail("exceptions", f"{label}: missing or unparseable expiry date (use YYYY-MM-DD).")
        elif date < today:
            fail("exceptions", f"{label}: expired on {date} — review, fix or consciously renew it.")
        elif (date - today).days <= 14:
            warn("exceptions", f"{label}: expires in {(date - today).days} day(s).")

def without_code_samples(text: str | None) -> str | None:
    """Blank the text quoted inside <pre>/<code>, keeping every newline so the
    line numbers reported for the rest of the file still point at the right place."""
    if text is None:
        return None
    return CODE_SAMPLE.sub(lambda m: m.group(1) + re.sub(r"[^\n]", " ", m.group(3)) + m.group(4), text)

def without_comments(text: str | None, suffix: str) -> str | None:
    """Blank comments for the file's language, keeping every newline."""
    if text is None:
        return None
    blank = lambda m: re.sub(r"[^\n]", " ", m.group(0))
    if suffix in SCRIPT_SUFFIXES or suffix in (".css", ".scss"):
        text = BLOCK_COMMENT.sub(blank, text)
    if suffix in SCRIPT_SUFFIXES:
        text = LINE_COMMENT.sub(blank, text)
    if suffix in MARKUP_SUFFIXES:
        text = HTML_COMMENT.sub(blank, text)
    return text

def scannable(path: Path) -> str | None:
    """The file as the source scan sees it: no quoted samples, no comments."""
    return without_comments(without_code_samples(read(path)), path.suffix.lower())

def check_aria_soup(root: Path, src: Path) -> None:
    """ARIA where native HTML already provides the semantics (A11Y.md §6):
    redundant roles, aria-label repeating the visible text, and aria-expanded
    hardcoded in markup that no script ever toggles."""
    redundant = re.compile(r"<(" + "|".join(REDUNDANT_ROLES) + r"|a)\b" + ATTRS + r">")
    dup_label = re.compile(r"<(a|button)\b" + ATTRS + r"\baria-label\s*=\s*[\"']([^\"']+)[\"']" + ATTRS + r">\s*([^<{]+?)\s*<", re.I)
    static_expanded = re.compile(r"\baria-expanded\s*=\s*[\"'](?:true|false)[\"']")
    dynamic_expanded = re.compile(r"aria-expanded(?!\s*=\s*[\"'](?:true|false)[\"'])|ariaExpanded")

    files = [(p, scannable(p)) for p in source_files(root, src)]
    # The script that toggles aria-expanded rarely lives beside the markup: `--src`
    # scopes the interface, so the search for the toggle spans the whole project.
    toggled = any(p.suffix in SCRIPT_SUFFIXES and dynamic_expanded.search(scannable(p) or "")
                  for p in source_files(root, root))

    for path, text in files:
        if not text or path.suffix in (".css", ".scss"):
            continue
        rel = path.relative_to(root)
        for match in redundant.finditer(text):
            tag, attrs = match.group(1).lower(), match.group(2)
            role = re.search(r"\brole\s*=\s*[\"']([\w-]+)[\"']", attrs)
            if not role:
                continue
            if tag == "a":
                if role.group(1) == "link" and re.search(r"\bhref\s*=", attrs):
                    fail("aria-soup", f"{rel}:{line_of(text, match.start())} — role=\"link\" on <a href>: "
                                      f"redundant role on a native element (ARIA Soup, A11Y.md §6)", match.group(0))
                continue
            if role.group(1) in REDUNDANT_ROLES.get(tag, ()):
                fail("aria-soup", f"{rel}:{line_of(text, match.start())} — role=\"{role.group(1)}\" on <{tag}>: "
                                  f"redundant role on a native element (ARIA Soup, A11Y.md §6)", match.group(0))
        for match in dup_label.finditer(text):
            label, visible = match.group(3), match.group(5)
            if re.sub(r"\s+", " ", label).strip().lower() == re.sub(r"\s+", " ", visible).strip().lower():
                warn("aria-soup", f"{rel}:{line_of(text, match.start())} — aria-label repeats the visible text "
                                  f"of <{match.group(1)}>. Drop it: when the two drift apart it becomes an "
                                  f"SC 2.5.3 failure (ARIA Soup, A11Y.md §6)", match.group(0))
        if not toggled:
            for match in static_expanded.finditer(text):
                warn("aria-soup", f"{rel}:{line_of(text, match.start())} — aria-expanded hardcoded and no script "
                                  f"in the project ever toggles it: a state that never updates is worse than "
                                  f"none (SC 4.1.2, ARIA Soup, A11Y.md §6)", match.group(0))

def check_placeholder_labels(root: Path, src: Path) -> None:
    """placeholder as the only label (A11Y.md §6, Placeholder Labels).

    axe accepts a placeholder as an accessible name, so this never fails axe.
    Labeled means: aria-label/aria-labelledby on the field, a <label for> (or
    htmlFor) pointing at its id in the same file, or the field wrapped in a
    <label>. Dynamic ids (`:id`, `id={…}`) cannot be resolved and are skipped.
    """
    field = re.compile(r"<(input|textarea)\b" + ATTRS + r">")
    skip_types = ("hidden", "submit", "button", "reset", "checkbox", "radio", "file", "range", "color", "image")
    for path in source_files(root, src):
        text = scannable(path)
        if text is None or path.suffix in (".css", ".scss", ".js", ".ts"):
            continue
        for match in field.finditer(text):
            attrs = match.group(2)
            if not re.search(r"\bplaceholder\s*=", attrs):
                continue
            kind = re.search(r"\btype\s*=\s*[\"']([\w-]+)", attrs)
            if kind and kind.group(1).lower() in skip_types:
                continue
            if re.search(r"\baria-label(ledby)?\s*=|\btitle\s*=", attrs):
                continue
            if re.search(r"(?<![:\w])id\s*=\s*\{", attrs) or re.search(r":id\s*=|v-bind:id", attrs):
                continue  # dynamic id — not resolvable statically
            id_match = re.search(r"(?<![:\w-])id\s*=\s*[\"']([^\"'{}]+)[\"']", attrs)
            if id_match and re.search(r"\b(?:for|htmlFor)\s*=\s*[\"']" + re.escape(id_match.group(1)) + r"[\"']", text):
                continue
            before = text[:match.start()]
            if before.rfind("<label") > before.rfind("</label>"):
                continue  # wrapped in a <label>
            fail("placeholder-label", f"{path.relative_to(root)}:{line_of(text, match.start())} — "
                                      f"<{match.group(1)}> labeled only by its placeholder. The label disappears "
                                      f"while typing; give it a visible <label> (A11Y.md §6)", match.group(0))

def test_extract_definitions_for_language(language: str) -> None:
    if language in _UNAVAILABLE:
        pytest.skip(f"grammar unavailable for {language}")

    spec = get_spec(language)
    assert spec is not None

    extracted = extract_file(SAMPLES[language], spec)

    names = {d.local_name for d in extracted.definitions}
    assert EXPECTED_DEFINITION_NAMES[language] <= names
    assert not extracted.parse_had_errors

def test_rust_impl_becomes_class_like_container() -> None:
    spec = get_spec("rust")
    assert spec is not None
    extracted = extract_file(SAMPLES["rust"], spec)
    kinds = {d.local_name: d.kind for d in extracted.definitions}
    assert kinds["Widget"] == "class"  # the impl block itself

def run_command_payload(command: str, shape: str = "command") -> dict:
    if shape == "command":
        payload = {"command": command}
    elif shape == "input.command":
        payload = {"input": {"command": command}}
    elif shape == "tool_input.command":
        payload = {"tool_input": {"command": command}}
    else:
        raise ValueError(shape)
    return run_hook(json.dumps(payload))

def test_alternate_command_field_shapes_are_checked() -> None:
    assert run_command_payload("rm -rf /", shape="input.command")["decision"] == "deny"
    assert run_command_payload("rm -rf /", shape="tool_input.command")["decision"] == "deny"

def test_bare_truncate_denied() -> None:
    result = run_command_payload("TRUNCATE users;")
    assert result["decision"] == "deny"

def test_drop_database_denied() -> None:
    result = run_command_payload("DROP DATABASE prod;")
    assert result["decision"] == "deny"

def test_drop_schema_denied() -> None:
    result = run_command_payload("DROP SCHEMA public;")
    assert result["decision"] == "deny"

def test_drop_table_denied() -> None:
