def test_empty_stdin_allows() -> None:
    result = run_hook("")
    assert result == {"decision": "allow"}

def test_git_push_force_allowed_with_confirm_marker() -> None:
    result = run_command_payload("git push --force origin main # CONFIRMED")
    assert result == {"decision": "allow"}

