        path = f"docs/{self.lang}/{relative}"
        if self.ref is None:
            file = self.root / path
            return file.read_text(encoding="utf-8") if file.is_file() else None
        result = subprocess.run(
            ["git", "-C", str(self.root), "show", f"{self.ref}:{path}"],
            capture_output=True, text=True,
        )
        return result.stdout if result.returncode == 0 else None

class Source:
    """Reads the docs tree either from the working directory or from a git ref."""

    def __init__(self, root: Path, lang: str, ref: str | None = None):
        self.root = root
        self.lang = lang
        self.ref = ref

    @property
    def label(self) -> str:
        return self.ref or "working tree"

    def read(self, relative: str) -> str | None:
        path = f"docs/{self.lang}/{relative}"
        if self.ref is None:
            file = self.root / path
            return file.read_text(encoding="utf-8") if file.is_file() else None
        result = subprocess.run(
            ["git", "-C", str(self.root), "show", f"{self.ref}:{path}"],
            capture_output=True, text=True,
        )
        return result.stdout if result.returncode == 0 else None

def line(cells):
        padded = []
        for i, cell in enumerate(cells):
            text = str(cell)
            padded.append(text.ljust(widths[i]) if i == 0 else text.rjust(widths[i]))
        return edge + sep.join(padded) + tail

def render(rows, headers, markdown: bool) -> str:
    widths = [max(len(str(r[i])) for r in [headers, *rows]) for i in range(len(headers))]
    sep = " | " if markdown else "  "
    edge = "| " if markdown else ""
    tail = " |" if markdown else ""

    def line(cells):
        padded = []
        for i, cell in enumerate(cells):
            text = str(cell)
            padded.append(text.ljust(widths[i]) if i == 0 else text.rjust(widths[i]))
        return edge + sep.join(padded) + tail

    out = [line(headers)]
    if markdown:
        out.append("|" + "|".join("-" * (w + 2) for w in widths) + "|")
    else:
        out.append("  ".join("-" * w for w in widths))
    out.extend(line(r) for r in rows)
    return "\n".join(out)

def luminance(rgb) -> float:
    def chan(c):
        c /= 255.0
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = (chan(c) for c in rgb[:3])
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def ratio(c1, c2) -> float:
    l1, l2 = sorted((luminance(c1), luminance(c2)), reverse=True)
    return (l1 + 0.05) / (l2 + 0.05)

def run_css(path, page_bg_tok, profile) -> int:
    floors = FLOORS[profile]
    page_bg = parse_color(page_bg_tok)
    if page_bg is None:
        sys.exit(f"ERROR: cannot parse --page-bg {page_bg_tok!r}")
    try:
        css = open(path, encoding="utf-8", errors="replace").read()
    except OSError as e:
        sys.exit(f"ERROR: {e}")
    seen = {}
    for tok in COLOR_RE.findall(css):
        c = parse_color(tok)
        if c is not None:
            seen.setdefault(fmt(composite(c, composite(page_bg, (255, 255, 255)))), tok)
    colors = list(seen.items())
    print(f"TRIAGE (not a verdict): {len(colors)} distinct colors in {path}; "
          f"pairs below the {profile} text floor ({floors['text']}:1) flagged.")
    flagged = 0
    for (hex1, tok1), (hex2, tok2) in itertools.combinations(colors, 2):
        r = ratio(parse_color(hex1), parse_color(hex2))
        if r < floors["text"]:
            flagged += 1
            band = "below UI floor (3:1)" if r < floors["ui"] else "text fails, large/UI may pass"
            print(f"  {hex1} × {hex2}: {r:.2f}:1 — {band}")
    print(f"{flagged} pair(s) flagged out of {len(colors) * (len(colors) - 1) // 2}. "
          "A flagged pair only matters if the two colors actually meet in the page — verify intent, then fix or record.")
    return 0  # triage never gates

def luminance(rgb) -> float:
    def chan(c):
        c /= 255.0
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = (chan(c) for c in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast(fg: str, bg: str) -> float:
    l1, l2 = sorted((luminance(hex_rgb(fg)), luminance(hex_rgb(bg))), reverse=True)
    return (l1 + 0.05) / (l2 + 0.05)

def self_test() -> int:
    """Built-in fixtures: one temp project per case, each check asserted by name."""
    ok = True
    for name, files, want_err, want_warn, forbid, *want_reg in SELF_TEST_CASES:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            for rel, content in files.items():
                path = root / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")
            run_checks(root, root / "src")
            errs = {c for lvl, c, *_ in findings if lvl == "ERROR"}
            warns = {c for lvl, c, *_ in findings if lvl == "WARN"}
            regs = {c for lvl, c, *_ in findings if lvl == "REGISTERED"}
            seen = errs | warns
            missing = (want_err - errs) | (want_warn - warns)
            unexpected = (forbid & seen) | (errs - want_err - want_warn)
            if want_reg:
                missing |= want_reg[0] - regs
                unexpected |= regs - want_reg[0]
            passed = not missing and not unexpected
            ok &= passed
            print(f"  {'✓' if passed else '✗'} {name}")
            if not passed:
                for lvl, c, m, _ in findings:
                    print(f"      {lvl} [{c}] {m[:110]}")
                if missing:
                    print(f"      missing: {sorted(missing)}")
                if unexpected:
                    print(f"      unexpected: {sorted(unexpected)}")
    print("self-test:", "PASS" if ok else "FAIL")
    return 0 if ok else 1

def resolve_imports(
    text: str,
    base_file: Path,
    workspace_root: Path,
    user_memory_root: Path,
    max_depth: int = MAX_IMPORT_DEPTH,
    visited: set[Path] | None = None,
    cumulative_bytes: list[int] | None = None,
) -> str:
    """Expands inline `@path/to/file` up to 5 hops with cycle & boundary checks."""
    if visited is None:
        visited = set()
    if cumulative_bytes is None:
        cumulative_bytes = [0]

    base_dir = base_file.parent if base_file.is_file() else base_file

    def _replace_import(match: re.Match) -> str:
        indent = match.group("indent")
        raw_target = match.group("path")

        try:
            target_path = resolve_and_sandbox_import(
                raw_ref=f"@{raw_target}",
                base_dir=base_dir,
                workspace_root=workspace_root,
                user_memory_root=user_memory_root,
            )
        except PermissionError as exc:
            return f"{indent}<!-- @import-forbidden-path: {exc} -->"
        except FileNotFoundError:
            return f"{indent}<!-- @import-missing-file: @{raw_target} -->"
        except (OSError, ValueError) as exc:
            return f"{indent}<!-- @import-error: {exc} -->"

        if target_path in visited:
            return f"{indent}<!-- @import-cycle-detected: @{raw_target} -->"

        if len(visited) >= max_depth:
            return f"{indent}<!-- @import-depth-exceeded: max {max_depth} hops -->"

        file_size = target_path.stat().st_size
        if file_size > MAX_FILE_BYTES:
            return f"{indent}<!-- @import-file-too-large: {file_size} bytes exceeds {MAX_FILE_BYTES} max -->"

        cumulative_bytes[0] += file_size
        if cumulative_bytes[0] > MAX_EXPANSION_BYTES:
            return f"{indent}<!-- @import-budget-exceeded: {cumulative_bytes[0]} bytes exceeds {MAX_EXPANSION_BYTES} max -->"

        sub_visited = set(visited)
        sub_visited.add(target_path)

        child_content = target_path.read_text(encoding="utf-8")
        child_expanded = resolve_imports(
            text=child_content,
            base_file=target_path,
            workspace_root=workspace_root,
            user_memory_root=user_memory_root,
            max_depth=max_depth,
            visited=sub_visited,
            cumulative_bytes=cumulative_bytes,
        )

        indented_lines = [
            f"{indent}{line}" if line.strip() else line
            for line in child_expanded.splitlines()
        ]
        return "\n".join(indented_lines)

    return _IMPORT_RE.sub(_replace_import, text)

